class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int buy = INT_MAX;
        int sell = 0;

        for(int i = 0; i < prices.size(); i++){
            buy = min(buy, prices[i]);
            sell= max(sell, prices[i]-buy);
        }
        return sell;
    }

};

class Solution {
public:
    int search(vector<int>& nums, int target) {
        int n=nums.size(); // Cantidad de elementos del arreglo

        // PRIMERA BÚSQUEDA BINARIA: encontrar dónde empieza el bloque derecho
        // (el punto de rotación). l y r marcan la zona donde puede estar.
        // r empieza en n-2 para poder comparar nums[m] con nums[m+1] sin salirnos del arreglo.
        int l=0,r=n-2;
        while(l<=r){
            int m=l+(r-l)/2; // Posición del medio (formato que evita desbordamiento)

            // Si nums[m] es mayor que el siguiente, encontramos el salto:
            // m+1 es donde empieza el bloque derecho. Guardamos esa posición y terminamos.
            if(nums[m]>nums[m+1]){
                l=m+1;
                break;
            }

            // Si nums[m] es mayor que el último elemento, m está en el bloque izquierdo,
            // así que el punto de rotación queda a la derecha.
            if(nums[n-1]<nums[m])l=m+1;
            // Si no, m está en el bloque derecho y el punto de rotación queda a la izquierda.
            else r=m-1;
        }
        // Aquí l es el índice donde empieza el bloque derecho (0 si no hubo rotación).

        // ELEGIR EL BLOQUE donde puede estar el target:
        // si target <= último elemento, solo puede estar en el bloque derecho: [l, n-1].
        if(nums[n-1]>=target){
            r=n-1;
        }
        // Si no, solo puede estar en el bloque izquierdo: [0, l].
        else{
            r=l;
            l=0;
        }

        // SEGUNDA BÚSQUEDA BINARIA: búsqueda binaria normal dentro del bloque elegido.
        while(l<=r){
            int m=l+(r-l)/2; // Posición del medio
            if(nums[m]==target)return m; // Lo encontramos: regresamos su índice
            if(nums[m]<target)l=m+1;     // El medio es menor: descartamos la mitad izquierda
            else r=m-1;                  // El medio es mayor: descartamos la mitad derecha
        }
        return -1; // Si el ciclo termina, el target no está en el arreglo
    }
};

class Solution {
#define inf 10000000 // Valor "infinito": mayor que cualquier dato posible de los arreglos
public:
    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
        int n=nums1.size(),m=nums2.size(); // Tamaños de cada arreglo

        // Hacemos que nums1 sea siempre el arreglo más pequeño.
        // La búsqueda binaria se hará sobre él y así eme2 nunca se sale de rango.
        if(n>m){
            swap(nums1,nums2);swap(n,m);
        }

        // l y r: rango de cuántos elementos podemos tomar de nums1 (de 0 a n).
        // mitad: tamaño que debe tener la mitad izquierda del arreglo combinado.
        // Con total impar, la izquierda queda con un elemento más (la mediana).
        int l=0,r=n,mitad=(n+m+1)/2;
        bool es_impar=(n+m)%2; // true si la cantidad total de datos es impar

        // BÚSQUEDA BINARIA sobre cuántos elementos tomamos de nums1
        while(l<=r){
            int mid=l+(r-l)/2;   // Elementos que tomamos de nums1 para la izquierda
            int eme2=mitad-mid;  // Elementos que faltan de nums2 para completar la mitad

            // Los 4 valores alrededor de los cortes.
            // Si no existe ese elemento, usamos -inf o inf para que no estorbe en las comparaciones.
            double iz1=(mid==0?-inf:nums1[mid-1]);   // Último de la izquierda en nums1
            double iz2=(eme2==0?-inf:nums2[eme2-1]); // Último de la izquierda en nums2
            double der1=(mid==n?inf:nums1[mid]);     // Primero de la derecha en nums1
            double der2=(eme2==m?inf:nums2[eme2]);   // Primero de la derecha en nums2

            // Corte correcto: todo lo de la izquierda es <= a todo lo de la derecha
            if(iz1<=der2&&iz2<=der1){
                // Total impar: la mediana es el mayor de la mitad izquierda
                if(es_impar)return(max(iz1,iz2));
                // Total par: promedio entre el mayor de la izquierda y el menor de la derecha
                return (max(iz1,iz2)+min(der1,der2))/2;
            }

            // Si iz1 > der2, tomamos demasiados elementos de nums1: tomamos menos
            if(iz1>der2)r=mid-1;
            // Si no, tomamos muy pocos de nums1: tomamos más
            else l=mid+1;
        }
        // Con entradas válidas siempre se encuentra un corte y nunca llegamos aquí pero leetcode pide retornar un valor
        return 0;
    }
};

class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int sum = nums[0];
        int maxSum = nums[0];
        for(int i = 1; i < nums.size(); i++){
            sum = max(nums[i], sum+nums[i]);
            maxSum = max(maxSum, sum);
        }
        return maxSum;
    }
};
